vec3 function1(vec2 uv, vec2 fragCoord, float time, float fn1, float fn2, float f3, float scale) {
    float f1 = sin(time*1.)*0.004+0.005;
    float f2 = fn1*sin(time*0.1)*32. + 20.;
    float l = length(uv.xy - 0.5);
    float d1 = f3*sin(-time*5. + f2*l);
    float d2 = float(( int( scale* fragCoord.x ) ^ int(scale * fragCoord.y) ) & 4)+fn2;
    float d3 = float(( int( scale* fragCoord.x + uv.x*d1) ^ int(scale * fragCoord.y + time*1. * d1*f1) ) & 4);
    float d4 = float(( int( scale* fragCoord.x) ^ int(scale * fragCoord.y + time*1. * d1*f1) ) & 4);
    float r = 0.1*(mod(d1,d2)*d3);
    float g = l;
    float b = log(d4);
    return vec3(r,g,b);
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;   

    vec3 f1 = function1(uv, fragCoord, 200. + iTime*0.1, 10.5, 5., 1.1, 0.1);
    vec3 f2 = function1(uv, fragCoord , -(400. + iTime)* (1.5 + 0.00001*f1.x), 1., 1.5, 2., 0.4);
    vec3 f3 = function1(uv, fragCoord, 100. + iTime, 1.0, 1.0, 4., 0.4);
    vec3 col = vec3((f3.z));//*(1. - f1.y));

    // Output to screen
    fragColor = vec4(col,0.5);
}
